CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE "BookingStatus" AS ENUM ('confirmed','cancelled','completed','no_show');
CREATE TABLE "AdminUser" ("id" text PRIMARY KEY, "username" text NOT NULL UNIQUE, "passwordHash" text NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "Service" ("id" text PRIMARY KEY, "name" text NOT NULL, "description" text, "durationMinutes" integer NOT NULL CHECK ("durationMinutes" BETWEEN 5 AND 480), "priceCents" integer CHECK ("priceCents" >= 0), "active" boolean NOT NULL DEFAULT true, "sortOrder" integer NOT NULL DEFAULT 0);
CREATE TABLE "Staff" ("id" text PRIMARY KEY, "name" text NOT NULL, "active" boolean NOT NULL DEFAULT true);
CREATE TABLE "StaffService" ("staffId" text NOT NULL REFERENCES "Staff"("id") ON DELETE CASCADE, "serviceId" text NOT NULL REFERENCES "Service"("id") ON DELETE CASCADE, PRIMARY KEY("staffId","serviceId"));
CREATE TABLE "BusinessHours" ("id" text PRIMARY KEY, "staffId" text NOT NULL REFERENCES "Staff"("id") ON DELETE CASCADE, "weekday" integer NOT NULL CHECK("weekday" BETWEEN 0 AND 6), "startMinute" integer NOT NULL, "endMinute" integer NOT NULL CHECK("endMinute" > "startMinute"), UNIQUE("staffId","weekday","startMinute"));
CREATE TABLE "Booking" ("id" text PRIMARY KEY, "code" text NOT NULL UNIQUE, "serviceId" text NOT NULL REFERENCES "Service"("id"), "staffId" text NOT NULL REFERENCES "Staff"("id"), "customerName" text NOT NULL, "phoneNormalized" text NOT NULL, "startsAt" timestamptz NOT NULL, "endsAt" timestamptz NOT NULL CHECK("endsAt" > "startsAt"), "status" "BookingStatus" NOT NULL DEFAULT 'confirmed', "manageTokenHash" text NOT NULL UNIQUE, "idempotencyKey" text UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "TimeBlock" ("id" text PRIMARY KEY, "staffId" text NOT NULL REFERENCES "Staff"("id"), "startsAt" timestamptz NOT NULL, "endsAt" timestamptz NOT NULL CHECK("endsAt" > "startsAt"), "reason" text, "active" boolean NOT NULL DEFAULT true);
CREATE TABLE "Occupancy" ("id" text PRIMARY KEY, "staffId" text NOT NULL REFERENCES "Staff"("id") ON DELETE CASCADE, "bookingId" text UNIQUE REFERENCES "Booking"("id") ON DELETE CASCADE, "blockId" text UNIQUE REFERENCES "TimeBlock"("id") ON DELETE CASCADE, "startsAt" timestamptz NOT NULL, "endsAt" timestamptz NOT NULL CHECK("endsAt" > "startsAt"), "active" boolean NOT NULL DEFAULT true, CHECK (("bookingId" IS NULL) <> ("blockId" IS NULL)));
ALTER TABLE "Occupancy" ADD CONSTRAINT "occupancy_no_overlap" EXCLUDE USING gist ("staffId" WITH =, tstzrange("startsAt","endsAt",'[)') WITH &&) WHERE ("active");
CREATE INDEX "Booking_startsAt_status_idx" ON "Booking"("startsAt","status");
CREATE TABLE "Settings" ("id" integer PRIMARY KEY DEFAULT 1 CHECK("id"=1), "businessName" text NOT NULL DEFAULT 'Al Corte', "publicPhone" text, "timezone" text NOT NULL DEFAULT 'America/Montevideo', "minAdvanceMinutes" integer NOT NULL DEFAULT 60, "maxAdvanceDays" integer NOT NULL DEFAULT 60, "slotStepMinutes" integer NOT NULL DEFAULT 15, "cancellationPolicy" text NOT NULL DEFAULT 'Cancelá o cambiá tu hora con anticipación contactando al local.');
CREATE TABLE "RateLimit" ("key" text PRIMARY KEY, "hits" integer NOT NULL, "resetAt" timestamptz NOT NULL);
